/* Own minimal Complianz simulator for integration tests (no vendor code). Mimics public identifiers only:
   window.complianz, cmplz_has_consent(), #cmplz-cookiebanner-container .cmplz-cookiebanner, .cmplz-* buttons,
   cookies cmplz_<category>=allow|deny and cmplz_banner-status. */
(function () {
  var cz = window.complianz;
  var sim = cz.sim || {};
  var CATS = ['preferences', 'statistics', 'marketing'];
  function getCookie(name) {
    var parts = document.cookie.split(';');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p.indexOf(name + '=') === 0) return p.slice(name.length + 1);
    }
    return null;
  }
  function setCookie(name, v) { document.cookie = name + '=' + v + '; path=/; max-age=31536000; SameSite=Lax'; }
  window.cmplz_has_consent = function (cat) {
    if (cat === 'functional') return true;
    return getCookie(cz.prefix + cat) === 'allow';
  };
  window.cmplz_is_bot = function () { return /googlebot|bingbot|wget|curl|nutch/i.test(navigator.userAgent); };
  window.cmplz_is_speedbot = function () { return /GTmetrix|pingdom|pingbot|Lighthouse/i.test(navigator.userAgent); };
  document.body ? document.body.classList.add('cmplz-' + cz.region) : null;
  if (getCookie(cz.prefix + 'banner-status') === 'dismissed') return;
  if (cz.region !== 'eu') return;

  function render() {
    var c = document.createElement('div');
    c.id = 'cmplz-cookiebanner-container';
    c.innerHTML =
      (sim.wall ? '<div class="cmplz-soft-cookiewall" style="position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:99998"></div>' : '') +
      '<div class="cmplz-cookiebanner cmplz-show optin cmplz-bottom-right" role="dialog" aria-modal="' + (sim.wall ? 'true' : 'false') + '" aria-labelledby="cmplz-message-title" ' +
      'style="position:fixed;right:16px;bottom:16px;width:420px;z-index:99999;background:#fff;color:#191e23;padding:16px;font:14px/1.4 sans-serif;box-shadow:0 0 12px rgba(0,0,0,.3)">' +
      '<div class="cmplz-header"><div id="cmplz-message-title" class="cmplz-title">Cookie-Zustimmung verwalten</div>' +
      '<button type="button" class="cmplz-close" aria-label="Dialog schließen" style="position:absolute;right:8px;top:8px">×</button></div>' +
      '<div class="cmplz-message">Um dir ein optimales Erlebnis zu bieten, verwenden wir Technologien wie Cookies. Die Zustimmung kann jederzeit widerrufen werden.</div>' +
      '<div class="cmplz-categories" style="display:none"><label><input type="checkbox" class="cmplz-consent-checkbox cmplz-statistics"> Statistiken</label></div>' +
      '<div class="cmplz-buttons" style="display:flex;gap:6px;margin-top:12px">' +
      '<button type="button" class="cmplz-btn cmplz-accept" style="padding:8px 12px;background:#1E73BE;color:#fff;border:0">Akzeptieren</button>' +
      (sim.reject ? '<button type="button" class="cmplz-btn cmplz-deny" style="padding:8px 12px;background:#f9f9f9;color:#222;border:1px solid #ccc">Ablehnen</button>' : '') +
      '<button type="button" class="cmplz-btn cmplz-view-preferences" style="padding:8px 12px;background:#f9f9f9;color:#222;border:1px solid #ccc">Einstellungen ansehen</button>' +
      '<button type="button" class="cmplz-btn cmplz-save-preferences" style="display:none">Einstellungen speichern</button>' +
      '</div>' +
      '<div class="cmplz-links"><a href="/cookie-richtlinie-eu/" class="cmplz-link cookie-statement">Cookie-Richtlinie</a> <a href="/impressum/" class="cmplz-link impressum">Impressum</a></div>' +
      '</div>';
    document.body.appendChild(c);
    if (sim.wall) document.body.style.overflow = 'hidden';
    function decide(all) {
      for (var i = 0; i < CATS.length; i++) setCookie(cz.prefix + CATS[i], all ? 'allow' : 'deny');
      setCookie(cz.prefix + 'functional', 'allow');
      setCookie(cz.prefix + 'banner-status', 'dismissed');
      setCookie(cz.prefix + 'policy_id', '17');
      c.remove();
      document.body.style.overflow = '';
    }
    c.querySelector('.cmplz-accept').addEventListener('click', function () { decide(true); });
    var deny = c.querySelector('.cmplz-deny');
    if (deny) deny.addEventListener('click', function () { decide(false); });
    c.querySelector('.cmplz-close').addEventListener('click', function () { c.querySelector('.cmplz-cookiebanner').style.display = 'none'; });
    c.querySelector('.cmplz-view-preferences').addEventListener('click', function () {
      c.querySelector('.cmplz-categories').style.display = 'block';
    });
  }
  if (document.body) render(); else document.addEventListener('DOMContentLoaded', render);
})();
